// r(a, b, word, emoji, flavor, tags, modifiers)
function r(
  a: string,
  b: string,
  word: string,
  emoji: string,
  flavor: string,
  tags: string[],
  modifiers: string[],
): Recipe {
  return { inputs: [a, b], result: { word, emoji, flavor, tags, modifiers } };
}

